/// <summary>
/// Compatibility projection for validation consumers that still inventory WPF method names. Runtime
/// command execution uses <see cref="MainWindow.FreeXRibbonHandlers"/> directly and never reflects.
/// </summary>
public static class FreeXRibbonHandlerMap
{
    public static IReadOnlyDictionary<string, string> Handlers { get; } =
        MainWindow.FreeXRibbonHandlers.ToDictionary(
            pair => pair.Key,
            pair => pair.Value.MethodName,
            StringComparer.Ordinal);
}
